// components/OrderPaymentModal.jsx
//
// Stripe payment modal used in two places:
//   1. Orders page  — "Pay Now" on an existing PLACED order
//   2. Checkout.jsx — after order is created for card payments
//
// Flow:
//   Step 1: POST /api/payments/create-payment-intent → { clientSecret, paymentIntentId }
//   Step 2: stripe.confirmCardPayment(clientSecret)  → Stripe handles card
//   Step 3: POST /api/payments/confirm               → mark COMPLETED in DB
//   Step 4: onSuccess(paymentIntent) called          → parent navigates

import { useState } from 'react';
import { loadStripe } from '@stripe/stripe-js';
import { Elements, CardElement, useStripe, useElements } from '@stripe/react-stripe-js';
import { api } from '../api/client';

// ─── Stripe publishable key ───────────────────────────────────────────────────
// Move to VITE_STRIPE_PUBLISHABLE_KEY env var for production.
const getStripe = () => {
  try {
    return loadStripe(
      import.meta.env.VITE_STRIPE_PUBLISHABLE_KEY ||
      'pk_test_51TNkmZLaPu9ajsblOXkmm0uFNncVcq0FktYW0TLa7iTlgPmbS5nnK0LNTaAy4rHNOGeD6p3zCjGYS34RwcevFf8m00QQQa5hQE'
    );
  } catch (err) {
    console.error('Critical: Failed to initialize Stripe.js', err);
    return null;
  }
};

const stripePromise = getStripe();

// ... (rest of the file remains similar until the public wrapper)

// ─── Public wrapper (adds Stripe Elements context) ────────────────────────────
export default function OrderPaymentModal({ order, onClose, onSuccess, onError }) {
  if (!order) return null;

  if (!stripePromise) {
    return (
      <div style={{
        position: 'fixed', inset: 0, zIndex: 1001,
        background: 'rgba(0,0,0,0.7)', display: 'flex', alignItems: 'center', justifyContent: 'center'
      }}>
        <div style={{ background: '#fff', padding: 30, borderRadius: 16, maxWidth: 400, textAlign: 'center' }}>
          <div style={{ fontSize: 40, marginBottom: 15 }}>⚠️</div>
          <h3 style={{ margin: '0 0 10px', color: '#111827' }}>Payment System Unavailable</h3>
          <p style={{ color: '#6b7280', fontSize: 14, lineHeight: 1.5 }}>
            We couldn't load the secure payment module (Stripe.js). 
            Please check your internet connection or disable any ad-blockers and try again.
          </p>
          <button onClick={onClose} style={{
            marginTop: 20, padding: '10px 20px', borderRadius: 8, 
            background: '#f97316', color: '#fff', border: 'none', fontWeight: 600, cursor: 'pointer'
          }}>Go back</button>
        </div>
      </div>
    );
  }

  return (
    <Elements stripe={stripePromise}>
      <PaymentForm
        order={order}
        onClose={onClose}
        onSuccess={onSuccess}
        onError={onError}
      />
    </Elements>
  );
}
